from dataclasses import dataclass, field
from enum import Enum, auto
from typing import Optional, Type
from civeng.hydraulics.fittings import (
    FittingType,
    Fitting, HorizontalBend, VerticalBend, Tee, AngleBranch, ClosedValve, BlankEnd, TaperThrust,
    create_fitting
)
from civeng.soils.soil_mechanics import Soil, SoilType, Consistency, WaterCondition, CoarseSoil, FineSoil, mid_range, UNIT_WEIGHT_WATER, create_soil

from abc import ABC
import math

# --- Enums ---

class ConcreteType(Enum):
    """Types of concrete."""
    UNREINFORCED = auto()
    REINFORCED = auto()

# --- Utilities (consider moving to utils.py) ---

def calc_height(diameter: float) -> float:
    """
    Calculates thrust block height in accordance with Ciria C816, Section 7.2.2.

    Args:
        diameter (float): Outside diameter of the pipe.

    Returns:
        float: Height of the thrust block.
    """
    return max(0.2, diameter / 2) * 2 + diameter

# --- Data Classes ---

@dataclass
class Concrete(ABC):
    """Properties of concrete."""
    concrete_type: ConcreteType
    # Optionally add strength properties if needed
    # compressive_strength: Optional[float] = None  # MPa
    # tensile_strength: Optional[float] = None  # MPa (for reinforced)

@dataclass
class ThrustBlock(Concrete):
    """
    Thrust block properties.

    Args:
        fitting (Fitting): The type of fitting used.
        soil (Soil): The soil object (CoarseSoil, FineSoil, etc).
        user_height (float): Height of the block.
        user_width (float): Width of the block.
        user_length (float): Length of the block.
        user_depth_block (float): Depth to block base.
    """
    fitting: Fitting
    soil: Soil
    user_height: float
    user_width: float
    user_length: float
    user_depth_block: float
    user_effective_depth: Optional[float]
    user_effective_height: Optional[float]

    def __post_init__(self):
        # Example validation
        if self.user_height <= 0:
            raise ValueError("user_height must be positive")
        if self.user_width <= 0:
            raise ValueError("user_width must be positive")
        if self.user_length <= 0:
            raise ValueError("user_length must be positive")
        if self.user_depth_block <= 0:
            raise ValueError("user_depth_block must be positive")
        if not isinstance(self.soil, Soil):
            raise TypeError("soil must be an instance of Soil or its subclass")

    @property
    def height(self) -> float:
        """
        Calculate the thrust block height based on fitting type and dimensions.

        Returns:
            float: Height of the thrust block.

        Raises:
            NotImplementedError: If fitting type is not recognized.
        """
        # Map fitting types to the correct diameter attribute
        if self.user_height is not None:
            return self.user_height
        
        group1 = (HorizontalBend, VerticalBend, ClosedValve, BlankEnd)
        group2 = (Tee, AngleBranch)

        if isinstance(self.fitting, group1):
            diameter = getattr(self.fitting, "diameter_outside", None)
        elif isinstance(self.fitting, group2):
            diameter = getattr(self.fitting, "diameter_outside_branch", None)
        elif isinstance(self.fitting, TaperThrust):
            diameter = getattr(self.fitting, "diameter_outside_large", None)
        else:
            diameter = None

        if diameter is None:
            raise NotImplementedError(
                f"Height calculation not implemented for fitting type: {type(self.fitting).__name__}"
            )

        return calc_height(diameter)

    @property
    def area_passive_face(self) -> float:
        """Returns the pressure bearing area of the thrust block (m2)."""
        return self.height * self.user_width

    @property
    def area_base_sliding(self) -> float:
        """
        Returns the base area of the thrust block.
        """
        return self.user_length * self.user_width
    
    @property
    def area_side_sliding(self) -> float:
        """
        Returns the sliding area per side of the thrust block if soil is of coarse category else returns 0.
        """
        if isinstance(self.soil, CoarseSoil):
            return self.height * self.user_length
        else:
            return 0
        
    @property
    def buoyancy_coefficient(self) -> float:
        """
        Returns buoyancy coefficient
        """
        return 1 - (self.soil.ground_water_level / self.user_depth_block)
    
    @property
    def sliding_resistance_base(self) -> Optional[float]:
        """
        Calculates net unit area soil pressure for the soil block.
        """
        if self.soil.unit_weight is None:
            raise ValueError("Unit weight is not defined.")
        if self.soil.soil_sliding_resistance_factor is None:
            raise ValueError("Sliding resistance factor is not defined.")
        if self.soil.soil_sliding_resistance_factor is None:
            raise ValueError("Sliding resistance factor is not defined.")
        
        sliding_resistance_factor = mid_range(self.soil.soil_sliding_resistance_factor)
        buoyancy_coefficient =  self.buoyancy_coefficient
        depth = self.user_effective_depth if self.user_effective_depth is not None else self.user_depth_block
        
        if isinstance(self.soil, CoarseSoil):
            if self.soil.friction_angle is None:
                raise ValueError("Friction angle is not defined.")
            friction_angle =  mid_range(self.soil.friction_angle) if isinstance(self.soil.friction_angle, tuple) else self.soil.friction_angle
            return ((self.soil.unit_weight - (buoyancy_coefficient * UNIT_WEIGHT_WATER)) 
                * depth
                * math.tan(math.radians(friction_angle))) / sliding_resistance_factor
        elif isinstance(self.soil, FineSoil):
            if self.soil.undrained_shear_strength is None:
                raise ValueError("Undrained Shear Strength is not defined.")
            undrained_shear_strength = mid_range(self.soil.undrained_shear_strength) if isinstance(self.soil.undrained_shear_strength, tuple) else self.soil.undrained_shear_strength
            soil_passive_resistance_factor = mid_range(self.soil.soil_sliding_resistance_factor)
            return undrained_shear_strength / soil_passive_resistance_factor
        else:
            return None

    @property
    def sliding_resistance_side(self) -> Optional[float]:
        """
        Calculates net unit area soil pressure for the soil block sides.
        """
        if isinstance(self.soil, FineSoil):
            return 0
        
        elif isinstance(self.soil, CoarseSoil):
            if self.soil.unit_weight is None:
                raise ValueError("Unit weight is not defined.")
            if self.soil.friction_angle is None:
                raise ValueError("Friction angle is not defined.")
            if self.soil.soil_sliding_resistance_factor is None:
                raise ValueError("Sliding resistance factor is not defined.")
            
            buoyancy_coefficient = self.buoyancy_coefficient
            friction_angle = mid_range(self.soil.friction_angle) if isinstance(self.soil.friction_angle, tuple) else self.soil.friction_angle
            depth = self.user_effective_depth if self.user_effective_depth is not None else self.user_depth_block
            height = self.user_effective_height if self.user_effective_height is not None else self.user_height
            soil_sliding_resistance_factor = mid_range(self.soil.soil_sliding_resistance_factor)
            active_coeff = self.soil.coefficient_active_earth_pressure
            return ((self.soil.unit_weight - (buoyancy_coefficient * UNIT_WEIGHT_WATER))
                * (depth - (height / 2))
                * active_coeff
                * math.tan(math.radians(friction_angle))) / soil_sliding_resistance_factor
        else:
            return None
        
    @property
    def net_unit_area_soil_pressure(self) -> Optional[float]:
        """
        Calculates net unit area soil pressure for the soil block.
        """

        if self.soil.unit_weight is None:
            raise ValueError("Unit weight is not defined.")
        if self.soil.soil_passive_resistance_factor is None:
            raise ValueError("Sliding resistance factor is not defined.")
        soil_passive_resistance_factor = mid_range(self.soil.soil_passive_resistance_factor)
        if isinstance(self.soil, CoarseSoil):
            buoyancy_coefficient = self.buoyancy_coefficient
            depth_block_base = self.user_effective_depth if self.user_effective_depth is not None else self.user_depth_block
            kp = self.soil.coefficient_passive_earth_pressure
            ka = self.soil.coefficient_active_earth_pressure
            height = self.user_effective_height if self.user_effective_height is not None else self.user_height
            return ((self.soil.unit_weight - (buoyancy_coefficient * UNIT_WEIGHT_WATER)) 
                * (depth_block_base - (height / 2)) 
                * (kp - ka)) / soil_passive_resistance_factor
        elif isinstance(self.soil, FineSoil):
            if self.soil.undrained_shear_strength is None:
                raise ValueError("Undrained Shear Strength is not defined.")
            undrained_shear_strength = mid_range(self.soil.undrained_shear_strength) if isinstance(self.soil.undrained_shear_strength, tuple) else self.soil.undrained_shear_strength
            return (2 * undrained_shear_strength) / soil_passive_resistance_factor
    
    @property
    def area_disturbed_passive(self) -> float:
        if isinstance(self.fitting, (ClosedValve, BlankEnd)):
            return 1.5 * self.fitting.diameter_outside \
            * (self.user_height + self.fitting.diameter_outside + self.fitting.depth_crown - self.user_depth_block)
        elif isinstance(self.fitting, (Tee, AngleBranch)):
            return 1.5 * self.fitting.diameter_outside_branch \
            * (self.user_height + self.fitting.diameter_outside_branch + self.fitting.depth_crown - self.user_depth_block)

        elif isinstance(self.fitting, TaperThrust):
            return 1.5 * self.fitting.diameter_outside_large \
            * (self.user_height + self.fitting.diameter_outside_large + self.fitting.depth_crown - self.user_depth_block)
        else:
            return 0
        
    @property
    def soil_resistance(self) -> float:
        if self.net_unit_area_soil_pressure is None:
            raise ValueError("Unit weight is not defined.")
        if self.sliding_resistance_base is None:
            raise ValueError("Unit weight is not defined.")
        if self.sliding_resistance_side is None:
            raise ValueError("Side sliding resistance is not defined")
        
        return self.net_unit_area_soil_pressure * (self.area_passive_face - self.area_disturbed_passive) \
            + (self.sliding_resistance_base * self.area_base_sliding) \
            + (2 * self.sliding_resistance_side * self.area_side_sliding)
    
    @property
    def overturning_level_arm(self) -> float:
        """
        Calculates the overturning lever arm for the thrust block based on fitting geometry.
        Returns 0 if no matching diameter attribute is found.
        """
        diameter_attrs = ["diameter_outside", "diameter_outside_main", "diameter_outside_large"]
        for attr in diameter_attrs:
            if hasattr(self.fitting, attr):
                diameter = getattr(self.fitting, attr)
                return self.user_depth_block - (self.fitting.depth_crown + diameter / 2)
        return 0
        
    @property
    def over_turning_moment(self) -> float:
        return self.fitting.thrust_force_resultant * self.overturning_level_arm
    
    @property
    def passive_face_restoring_moment(self) -> float:
        if self.net_unit_area_soil_pressure:
            return self.net_unit_area_soil_pressure * self.user_width * ((self.user_height ** 2 )/ 3)
        else:
            return 0

    @property
    def net_disturbing_moment(self) -> float:
        return self.over_turning_moment - self.passive_face_restoring_moment
    
    @property
    def ultimate_vertical_bearing_capacity(self) -> float:
        if not self.soil.unit_weight:
         return 0
        if isinstance(self.soil, CoarseSoil):
            return (0.5 * (self.soil.unit_weight - (self.buoyancy_coefficient * UNIT_WEIGHT_WATER) * self.soil.bearing_capacity_coefficients.n_y) \
                    * min(self.user_length, self.user_width) \
                    + (self.soil.unit_weight - (self.buoyancy_coefficient * UNIT_WEIGHT_WATER)* (self.soil.bearing_capacity_coefficients.n_q - 1) * self.user_depth_block))
        elif isinstance(self.soil, FineSoil):
            if not self.soil.undrained_shear_strength:
                return 0
            if not self.soil.soil_passive_resistance_factor:
                return 0
            return (6 * mid_range(self.soil.undrained_shear_strength) / mid_range(self.soil.soil_passive_resistance_factor))
        else:
            return 0

def create_thrust_block(
    fitting: Fitting,
    soil: Soil,
    user_height: float,
    user_width: float,
    user_length: float,
    user_depth_block: float,
    user_effective_depth : float | None = None,
    user_effective_height: float | None = None
) -> ThrustBlock:
    """
    Factory function to create a ThrustBlock instance with validation.
    """
    return ThrustBlock(
        concrete_type=ConcreteType.UNREINFORCED,
        fitting=fitting, 
        soil=soil, 
        user_height=user_height, 
        user_width=user_width, 
        user_length=user_length,
        user_depth_block=user_depth_block,
        user_effective_depth=user_effective_depth,
        user_effective_height=user_effective_height)

def main():
    # ========== Example One ==========
    print("========== Testing with Example One of Ciria C816 ==========\n")
    soil_one = create_soil(
        soil_type = SoilType.GRAVEL,
        consistency=Consistency.MEDIUM_DENSE,
        ground_water_level=0.8,
        water_condition=WaterCondition.BELOW_WATER
    )

    fitting = create_fitting(FittingType.TAPER_THRUST, maximum_design_pressure=1200, depth_crown=1, diameter_outside_large=0.63, diameter_outside_small= 0.43)

    thrust_block_one = create_thrust_block(
        fitting = fitting,
        soil = soil_one,
        user_height= 1.8,
        user_width=3.5,
        user_length=2.5,
        user_depth_block=2.3,
    )
    print(f"Net passive soil pressure: {thrust_block_one.net_unit_area_soil_pressure:.1f} kN/m2")
    print(f"Base sliding resistance: {thrust_block_one.sliding_resistance_base:.1f}")
    print(f"Side sliding resistance: {thrust_block_one.sliding_resistance_side:.1f}")
    print(f"Passive face area: {thrust_block_one.area_passive_face:.1f}")
    print(f"Base sliding area: {thrust_block_one.area_base_sliding:.1f}")
    print(f"Sliding area per side: {thrust_block_one.area_side_sliding:.1f}")
    print(f"Disturbed passive area due to pipe trench: {thrust_block_one.area_disturbed_passive:.1f}")
    print(f"Soil resistance (Rs): {thrust_block_one.soil_resistance:.1f}")
    print(f"Thrust force: {thrust_block_one.fitting.thrust_force_resultant:.1f}")
    if thrust_block_one.soil_resistance > thrust_block_one.fitting.thrust_force_resultant:
        print(f"{thrust_block_one.soil_resistance:.1f} > {thrust_block_one.fitting.thrust_force_resultant:.1f} kN Pass thrust resistance")
    else:
        print(f"WARNING! {thrust_block_one.soil_resistance:.1f} < {thrust_block_one.fitting.thrust_force_resultant:.1f}")
    
    # ========== Example Two ==========
    print("========== Testing with Example Two of Ciria C816 ==========\n")
    soil_one = create_soil(
        soil_type = SoilType.CLAY,
        consistency=Consistency.FIRM,
        ground_water_level=0.8,
        water_condition=WaterCondition.BELOW_WATER,
        user_undrained_shear_strength=50
    )

    fitting = create_fitting(FittingType.VERTICAL_BEND, maximum_design_pressure=1200, depth_crown=1, diameter_outside=0.63, angle = 45, radius=0)

    thrust_block_three = create_thrust_block(
        fitting = fitting,
        soil = soil_one,
        user_height= 1.2,
        user_width=1.6,
        user_length=1.7,
        user_depth_block=2.2,
    )
    if isinstance(thrust_block_three.soil, FineSoil):
        print(f"Undrained shear strength: {thrust_block_three.soil.undrained_shear_strength}")
    # Sliding resistance displacement limitation factor in example uses 3 as mid-value? even though range for firm clay is (3, 4)
    print(f"Sliding resistance displacement limitation factor: {thrust_block_three.soil.soil_passive_resistance_factor}")
    print(f"Net passive soil pressure: {thrust_block_three.net_unit_area_soil_pressure:.1f} kN/m2")
    print(f"Base sliding resistance: {thrust_block_three.sliding_resistance_base:.1f}")
    print(f"Side sliding resistance: {thrust_block_three.sliding_resistance_side:.1f}")
    print(f"Passive face area: {thrust_block_three.area_passive_face:.1f}")
    print(f"Base sliding area: {thrust_block_three.area_base_sliding:.1f}")
    print(f"Sliding area per side: {thrust_block_three.area_side_sliding:.1f}")
    print(f"Disturbed passive area due to pipe trench: {thrust_block_three.area_disturbed_passive:.1f}")
    print(f"Soil resistance (Rs): {thrust_block_three.soil_resistance:.1f}")
    print(f"Thrust force: {thrust_block_three.fitting.thrust_force_resultant:.1f}")
    if thrust_block_three.soil_resistance > thrust_block_three.fitting.thrust_force_resultant:
        print(f"{thrust_block_three.soil_resistance:.1f} > {thrust_block_three.fitting.thrust_force_resultant:.1f} kN Pass thrust resistance")
    else:
        print(f"WARNING! {thrust_block_three.soil_resistance:.1f} < {thrust_block_three.fitting.thrust_force_resultant:.1f}")
    print(f"Overturning moment lever arm: {thrust_block_three.overturning_level_arm:.1f}")
    print(f"Overturning moment: {thrust_block_three.over_turning_moment:.1f}")
    print(f"Passive face restoring moment: {thrust_block_three.passive_face_restoring_moment:.1f}")
    print(f"Net disturbing moment: {thrust_block_three.net_disturbing_moment:.1f}")

     # ========== Example Three ==========
    print("========== Testing with Example Three of Ciria C816 ==========\n")
    if isinstance(thrust_block_three.soil, FineSoil):
        print(f"Undrained shear strength: {thrust_block_three.soil.undrained_shear_strength}")
    # Sliding resistance displacement limitation factor in example uses 3 as mid-value? even though range for firm clay is (3, 4)
    print(f"Sliding resistance displacement limitation factor: {thrust_block_three.soil.soil_passive_resistance_factor}")
    print(f"Net passive soil pressure: {thrust_block_three.net_unit_area_soil_pressure:.1f} kN/m2")
    print(f"Base sliding resistance: {thrust_block_three.sliding_resistance_base:.1f}")
    print(f"Side sliding resistance: {thrust_block_three.sliding_resistance_side:.1f}")
    print(f"Passive face area: {thrust_block_three.area_passive_face:.1f}")
    print(f"Base sliding area: {thrust_block_three.area_base_sliding:.1f}")
    print(f"Sliding area per side: {thrust_block_three.area_side_sliding:.1f}")
    print(f"Disturbed passive area due to pipe trench: {thrust_block_three.area_disturbed_passive:.1f}")
    print(f"Soil resistance (Rs): {thrust_block_three.soil_resistance:.1f}")
    print(f"Thrust force: {thrust_block_three.fitting.thrust_force_resultant:.1f}")
    if thrust_block_three.soil_resistance > thrust_block_three.fitting.thrust_force_resultant:
        print(f"{thrust_block_three.soil_resistance:.1f} > {thrust_block_three.fitting.thrust_force_resultant:.1f} kN Pass thrust resistance")
    else:
        print(f"WARNING! {thrust_block_three.soil_resistance:.1f} < {thrust_block_three.fitting.thrust_force_resultant:.1f}")
    print(f"Ultimate ground bearing resiatnce: {thrust_block_three.ultimate_vertical_bearing_capacity}")
if __name__ == "__main__":
    main()